{"source":"#include <stdio.h>

int main(int argc, char *argv[]) {
    int i,a[3],b[3];
    for(i=0;i<3;i++){
        scanf("%d%d",&a[i],&b[i]);
    }
    int ok=0;
    int x[3],y[3];
    x[0]=a[0]; y[0]=b[0];
    x[1]=a[1]; y[1]=b[1];
    x[2]=a[2]; y[2]=b[2];
    for(int p=0;p<2;p++){
        int W=x[0],H=y[0];
        int w1=x[1],h1=y[1],w2=x[2],h2=y[2];
        if((w1+w2<=W && h1<=H && h2<=H) ||
           (w1+h2<=W && h1<=H && w2<=H) ||
           (h1+w2<=W && w1<=H && h2<=H) ||
           (h1+h2<=W && w1<=H && w2<=H)) ok=1;
        int t;
        t=x[0]; x[0]=y[0]; y[0]=t;
    }
    if(ok) printf("YES\n");
    else printf("NO\n");
    return 0;
}"}
